UPDATE product
product_name = #{productName}, category = #{category}, brand = #{brand}, model = #{model}, price = #{price}, stock = #{stock}, description = #{description}, status = #{status},
WHERE product_id = #{productId}

UPDATE product
SET stock = stock - #{count},
    version = version + 1
WHERE product_id = #{productId}
  AND version = #{version}
  AND stock >= #{count}
